import re
def money(x):
    """parse VN money strings: 1tr090, 45k, 1,5tr, 45.000đ, 1,500.0000, plain numbers"""
    if x is None or (isinstance(x,float) and x!=x): return float('nan')
    if isinstance(x,(int,float)): return float(x)
    s=str(x).strip().lower().replace('đ','').replace('₫','').replace('vnd','').replace(' ','')
    m=re.fullmatch(r'(\d+)(?:[,.](\d+))?tr(\d*)',s)
    if m:
        a,b,c=m.groups()
        if b: return float(a+'.'+b)*1e6
        return int(a)*1e6+(int(c.ljust(3,'0')[:3])*1000 if c else 0)
    m=re.fullmatch(r'(\d+(?:[.,]\d+)?)k',s)
